// Service worker: precaches the whole game so it installs as a PWA and runs fully offline.
// The VERSION and ASSETS block is regenerated by `npm run build:sw` (tools/build-sw.mjs); the GitHub Pages
// workflow runs it on every deploy so a new release always gets a fresh cache.

/* BUILD:START */
const VERSION = '6c311b8abea3';
const ASSETS = [
  "./",
  "./css/style.css",
  "./fonts/outfit-latin-wght-normal.woff2",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-32.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon-maskable-512.png",
  "./icons/icon.svg",
  "./index.html",
  "./js/app.js",
  "./js/audio.js",
  "./js/buildings.js",
  "./js/city.js",
  "./js/config.js",
  "./js/game.js",
  "./js/geom.js",
  "./js/icons.js",
  "./js/input.js",
  "./js/main.js",
  "./js/network.js",
  "./js/render/buildingmesh.js",
  "./js/render/flow.js",
  "./js/render/markers.js",
  "./js/render/materials.js",
  "./js/render/overlay.js",
  "./js/render/roadgeom.js",
  "./js/render/roads.js",
  "./js/render/terrainmesh.js",
  "./js/render/theme.js",
  "./js/render/vehicles.js",
  "./js/render/view.js",
  "./js/roadplan.js",
  "./js/router.js",
  "./js/save.js",
  "./js/signaledit.js",
  "./js/signals.js",
  "./js/sim.js",
  "./js/terrain.js",
  "./js/tools.js",
  "./js/ui.js",
  "./js/util.js",
  "./manifest.webmanifest",
  "./vendor/three.core.js",
  "./vendor/three.module.js"
];
/* BUILD:END */

const PREFIX = 'one-more-lane-';
const CACHE = PREFIX + VERSION;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(ASSETS.map((u) => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  // The app shell is the same page for every navigation.
  if (req.mode === 'navigate') {
    event.respondWith(caches.match('./index.html').then((hit) => hit || fetch(req).catch(() => caches.match('./'))));
    return;
  }
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then(
      (hit) =>
        hit ||
        fetch(req).then((res) => {
          if (res.ok) {
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put(req, copy));
          }
          return res;
        }),
    ),
  );
});
